<?php namespace App\Services\WhatsApp; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Log; class RuangWaProvider implements WhatsAppProviderInterface { protected $token; public function __construct(string $token = '') { $this->token = $token ?: env("WA_RUANGWA_TOKEN"); } public function sendMessage(string $phone, string $message): bool { try { $response = Http::post("https://ruangwa.id/v2/api/send-message.php", ["token" => $this->token, "number" => $phone, "message" => $message]); return $response->successful(); } catch (\Exception $e) { Log::error("RuangWA API Err: " . $e->getMessage()); return false; } } 
public function sendBatch(array $messages, ?string $delay = '2-5'): array { return ['status' => false, 'reason' => 'Not supported by RuangWA provider yet.']; }
public function reschedule(int $messageId, int $newSchedule, ?string $delay = null): array { return ['status' => false, 'reason' => 'Not supported by RuangWA provider yet.']; }
}
